DO $test$
DECLARE u uuid;bid uuid:=gen_random_uuid();emp uuid:=gen_random_uuid();lt uuid:=gen_random_uuid();plan uuid;req uuid:=gen_random_uuid();r jsonb;calc jsonb;payload jsonb;rules jsonb;owd jsonb;rev timestamptz;owd_rev timestamptz;denied boolean;count_before bigint;pending jsonb;new_req uuid;
BEGIN
 IF public.frindly_market_environment_status()->>'project_ref' IS DISTINCT FROM 'smvvevrtjqkflyqkyape' THEN RAISE EXCEPTION 'Market only';END IF;
 SELECT id INTO u FROM auth.users a WHERE NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=a.id) ORDER BY id LIMIT 1;
 SELECT id INTO plan FROM public.plans WHERE 'payroll'=ANY(included_modules) ORDER BY cardinality(included_modules) DESC NULLS LAST LIMIT 1;
 IF u IS NULL OR plan IS NULL THEN RAISE EXCEPTION 'Fixture prerequisites missing';END IF;
 BEGIN
  INSERT INTO public.businesses(id,name) VALUES(bid,'Market statutory leave fixture');INSERT INTO public.profiles(id,business_id,active_business_id,full_name,role,is_super_admin) VALUES(u,bid,bid,'Statutory leave fixture','owner',false);INSERT INTO public.business_memberships(business_id,user_id,role,status) VALUES(bid,u,'owner','active');
  INSERT INTO public.subscriptions(business_id,plan_id,status,current_period_end,trial_ends_at) VALUES(bid,plan,'trialing',now()+interval '30 days',now()+interval '30 days');
  INSERT INTO public.payroll_settings(business_id,country_code) VALUES(bid,'NZ');INSERT INTO public.payroll_employees(id,business_id,employee_number,first_name,last_name,start_date) VALUES(emp,bid,'ST-1','Statutory','Fixture','2020-01-01');INSERT INTO public.payroll_leave_types(id,business_id,name,paid,statutory_leave_code) VALUES(lt,bid,'Statutory fixture',true,'sick_leave');
  SELECT coalesce(jsonb_agg(jsonb_build_object('type',rule_type,'key',rule_key,'numeric_value',numeric_value,'text_value',text_value,'json_value',json_value,'effective_from',effective_from,'effective_to',effective_to,'source_note',source_note)),'[]') INTO rules FROM public.country_payroll_rules WHERE country_code='NZ' AND active AND effective_from<='2026-10-01' AND (effective_to IS NULL OR effective_to>='2026-10-01');
  owd:='{"determination":"yes","method":"employer_determined","evidence_snapshot":{"date":"2026-10-01","fixture":true},"employer_reason":"Confirmed fixture roster"}';
  calc:=jsonb_build_object('business_id',bid,'employee_id',emp,'leave_type_id',lt,'statutory_leave_code','sick_leave','calculation_type','sick_leave','relevant_from','2026-10-01','relevant_to','2026-10-01','rule_version','V61.73-P4B.1','rules_snapshot',jsonb_build_object('country','NZ','rules',rules),'input_snapshot','{"leave_code":"sick_leave","statutory_quantity":1,"statutory_unit":"days","eligibility":{"status":"eligible"},"entitlement":{"status":"calculated","available_days":10}}'::jsonb,'owd_evidence_snapshot',owd->'evidence_snapshot','rdp_amount',200,'adp_amount',NULL,'selected_method','rdp','selected_amount',200,'confirmation_state','confirmed','explanation_snapshot','{"status":"calculated","reasons":[]}'::jsonb);
  payload:=jsonb_build_object('calculation',calc,'owd',owd,'entitlement','{"period_start":"2026-01-01","period_end":"2026-12-31","grant_days":10,"carry_forward_days":0}'::jsonb,'display_hours',8,'notes','Fixture leave');
  PERFORM set_config('request.jwt.claim.sub',u::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
  r:=public.v6230_record_statutory_leave(emp,req,NULL,NULL,payload);IF r->'transaction'->>'statutory_unit'<>'days' OR (r->'entitlement'->>'used_days')::numeric<>1 OR (r->'calculation'->>'selected_amount')::numeric<>200 THEN RAISE EXCEPTION 'Statutory bundle result wrong';END IF;
  IF public.v6230_record_statutory_leave(emp,req,NULL,NULL,payload)<>r THEN RAISE EXCEPTION 'Replay failed';END IF;
  IF (SELECT count(*) FROM public.payroll_leave_transactions WHERE employee_id=emp)<>1 OR (SELECT count(*) FROM public.payroll_statutory_leave_calculations WHERE employee_id=emp)<>1 THEN RAISE EXCEPTION 'Replay duplicated statutory records';END IF;
  denied:=false;BEGIN PERFORM public.v6230_record_statutory_leave(emp,req,NULL,NULL,jsonb_set(payload,'{notes}','"Different"'));EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Changed retry accepted';END IF;
  rev:=(r->'entitlement'->>'updated_at')::timestamptz;owd_rev:=(r->'owd'->>'updated_at')::timestamptz;
  denied:=false;BEGIN PERFORM public.v6230_record_statutory_leave(emp,gen_random_uuid(),owd_rev,rev,payload);EXCEPTION WHEN unique_violation THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Duplicate confirmed leave accepted';END IF;
  payload:=jsonb_set(jsonb_set(payload,'{calculation,relevant_from}','"2026-10-02"'),'{calculation,relevant_to}','"2026-10-02"');payload:=jsonb_set(jsonb_set(payload,'{owd,evidence_snapshot,date}','"2026-10-02"'),'{calculation,owd_evidence_snapshot,date}','"2026-10-02"');
  denied:=false;BEGIN PERFORM public.v6230_record_statutory_leave(emp,gen_random_uuid(),NULL,NULL,payload);EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied OR EXISTS(SELECT 1 FROM public.payroll_owd_determinations WHERE employee_id=emp AND relevant_date='2026-10-02') THEN RAISE EXCEPTION 'Stale entitlement saved or left partial OWD';END IF;
  r:=public.v6230_record_statutory_leave(emp,gen_random_uuid(),NULL,rev,payload);IF (r->'entitlement'->>'used_days')::numeric<>2 THEN RAISE EXCEPTION 'Used days did not increment from database';END IF;rev:=(r->'entitlement'->>'updated_at')::timestamptz;
  denied:=false;BEGIN PERFORM public.v6230_record_statutory_leave(emp,gen_random_uuid(),NULL,rev,jsonb_set(payload,'{calculation,selected_amount}','"NaN"'));EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'NaN accepted';END IF;
  denied:=false;BEGIN PERFORM public.v6230_record_statutory_leave(emp,gen_random_uuid(),NULL,rev,jsonb_set(payload,'{calculation,rules_snapshot,rules}','[]'));EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Unverified rules accepted';END IF;
  denied:=false;BEGIN UPDATE public.payroll_statutory_leave_entitlements SET used_days=0 WHERE employee_id=emp;EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Direct entitlement overwrite allowed';END IF;
  denied:=false;BEGIN INSERT INTO public.payroll_leave_transactions(business_id,employee_id,leave_type_id,transaction_date,transaction_type,hours,statutory_quantity,statutory_unit,statutory_leave_code) VALUES(bid,emp,lt,'2026-10-03','taken',8,1,'days','sick_leave');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Old split statutory writer allowed';END IF;
  denied:=false;BEGIN UPDATE public.payroll_statutory_leave_calculations SET selected_amount=999 WHERE employee_id=emp;EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Confirmed calculation overwrite allowed';END IF;
  -- A second writer must present the current OWD revision, and cannot overdraw the stored period.
  denied:=false;BEGIN PERFORM public.v6230_record_statutory_leave(emp,gen_random_uuid(),NULL,rev,payload);EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Stale OWD accepted';END IF;
  pending:=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{calculation,relevant_from}','"2026-10-03"'),'{calculation,relevant_to}','"2026-10-03"'),'{owd,evidence_snapshot,date}','"2026-10-03"'),'{calculation,owd_evidence_snapshot,date}','"2026-10-03"');
  denied:=false;BEGIN PERFORM public.v6230_record_statutory_leave(emp,gen_random_uuid(),NULL,rev,jsonb_set(pending,'{calculation,input_snapshot,statutory_quantity}','9'));EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied OR EXISTS(SELECT 1 FROM public.payroll_owd_determinations WHERE employee_id=emp AND relevant_date='2026-10-03') THEN RAISE EXCEPTION 'Overdraw left partial statutory evidence';END IF;
  -- Abort the caller transaction after a complete save to verify all its child writes roll back together.
  new_req:=gen_random_uuid();BEGIN PERFORM public.v6230_record_statutory_leave(emp,new_req,NULL,rev,pending);RAISE EXCEPTION USING ERRCODE='P6231',MESSAGE='Abort complete fixture save';EXCEPTION WHEN SQLSTATE 'P6231' THEN NULL;END;
  EXECUTE 'RESET ROLE';
  IF EXISTS(SELECT 1 FROM public.payroll_statutory_leave_operations WHERE id=new_req) OR EXISTS(SELECT 1 FROM public.payroll_owd_determinations WHERE employee_id=emp AND relevant_date='2026-10-03') OR (SELECT used_days FROM public.payroll_statutory_leave_entitlements WHERE employee_id=emp)<>2 THEN RAISE EXCEPTION 'Caller abort left partial save';END IF;
  EXECUTE 'SET LOCAL ROLE authenticated';
  -- Ineligible results have no OWD; unconfirmed evidence never deducts entitlement or creates a leave entry.
  pending:=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{calculation,confirmation_state}','"not_required"'),'{calculation,explanation_snapshot}','{"status":"not_eligible","reasons":[]}'),'{calculation,input_snapshot}','{"leave_code":"sick_leave","eligibility":{"status":"not_eligible"}}'),'{owd}','null');pending:=jsonb_set(pending,'{calculation,owd_evidence_snapshot}','{}');
  r:=public.v6230_record_statutory_leave(emp,gen_random_uuid(),NULL,NULL,pending);IF r->'transaction'<>'null'::jsonb OR r->'owd'<>'null'::jsonb OR r->'entitlement'<>'null'::jsonb OR (SELECT used_days FROM public.payroll_statutory_leave_entitlements WHERE employee_id=emp)<>2 THEN RAISE EXCEPTION 'Ineligible result changed balances';END IF;
  EXECUTE 'RESET ROLE';INSERT INTO public.business_member_access_overrides(business_id,membership_id,area,can_read,can_write) SELECT bid,id,'payroll',true,false FROM public.business_memberships WHERE business_id=bid AND user_id=u;EXECUTE 'SET LOCAL ROLE authenticated';
  denied:=false;BEGIN PERFORM public.v6230_record_statutory_leave(emp,gen_random_uuid(),NULL,rev,payload);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Read-only user wrote leave';END IF;
  EXECUTE 'RESET ROLE';DELETE FROM public.business_member_access_overrides WHERE business_id=bid;PERFORM set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
  denied:=false;BEGIN PERFORM public.v6230_record_statutory_leave(emp,gen_random_uuid(),NULL,rev,payload);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Foreign user wrote leave';END IF;EXECUTE 'RESET ROLE';
  IF has_function_privilege('anon','public.v6230_record_statutory_leave(uuid,uuid,timestamp with time zone,timestamp with time zone,jsonb)','EXECUTE') OR has_table_privilege('authenticated','public.payroll_statutory_leave_operations','SELECT') OR EXISTS(SELECT 1 FROM public.payroll_pay_runs WHERE business_id=bid) OR EXISTS(SELECT 1 FROM public.payroll_payslips WHERE business_id=bid) THEN RAISE EXCEPTION 'Unsafe API grants or unrelated payroll writes';END IF;
  RAISE EXCEPTION USING ERRCODE='P6230',MESSAGE='Rollback statutory fixture';
 EXCEPTION WHEN SQLSTATE 'P6230' THEN NULL;END;
 IF EXISTS(SELECT 1 FROM public.businesses WHERE id=bid) OR EXISTS(SELECT 1 FROM public.payroll_statutory_leave_operations WHERE id=req) THEN RAISE EXCEPTION 'Statutory fixture leaked';END IF;RAISE NOTICE 'Statutory leave fixture passed; all data rolled back';
END;$test$;
